//
// Lookup in the generated table of Tcl's library scripts (the table itself
// is generated by cmake/Tcl.cmake into the hefesto::tcl target).

#include "hefesto/script/tcl/embedded_library.hpp"

#include <algorithm>

namespace hefesto::script {

std::optional<std::string_view> find_embedded_file(std::string_view path) noexcept {
  const auto files = embedded_library();
  const auto it = std::lower_bound(files.begin(), files.end(), path,
                                   [](const EmbeddedFile& file, std::string_view key) { return file.path < key; });
  if (it == files.end() || it->path != path) {
    return std::nullopt;
  }
  return it->content;
}

}  // namespace hefesto::script
